# frozen_string_literal: true

# Translate the controlled Markdown syntax generated by bg-export, not arbitrary Markdown.
module OutputFormat
  def self.org(text)
    text = text.gsub(/  \n/) { ' ' + ('\\' * 2) + "\n" }
    text.lines.map do |line|
      heading = line.match(/\A(\#{1,6}) (.*?)(\n)?\z/)
      if heading
        "#{'*' * heading[1].length} #{inline(heading[2])}\n"
      else
        inline(line)
      end
    end.join
  end

  def self.inline(text)
    text.gsub(/\[\^([^\]]+)\]:?/, '[fn:\1]')
        .gsub(/\*\*(.+?)\*\*/, '*\1*')
        .gsub(/(?<!\w)_(.+?)_(?!\w)/, '/\1/')
  end
end
